import 'package:flutter/material.dart';
import '../services/account_center_service.dart';
class AdPreferencesScreen extends StatefulWidget{const AdPreferencesScreen({super.key});@override State<AdPreferencesScreen> createState()=>_AdPreferencesScreenState();} class _AdPreferencesScreenState extends State<AdPreferencesScreen>{bool personalized=false,activityBased=false;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Ad preference')),body:ListView(children:[SwitchListTile(title:const Text('Personalized ads'),subtitle:const Text('Control whether ads are personalized using activity signals.'),value:personalized,onChanged:(v){setState(()=>personalized=v);AccountCenterService.setValue('personalizedAds',v);}),SwitchListTile(title:const Text('Activity-based ads'),subtitle:const Text('Allow activity signals to influence ad relevance.'),value:activityBased,onChanged:(v){setState(()=>activityBased=v);AccountCenterService.setValue('activityBasedAds',v);}),const ListTile(title:Text('Ad topics'),subtitle:Text('Ad topics and provider controls can be expanded when KREVZY advertising services are enabled.'))]));}